function ncPick(ids){const L=ST('needCover',[]);const subj=L.find(x=>x.id===ids[0]).subj;const cands=STAFF.filter(s=>s.campus==='c1'&&s.dept!=='leadership').map(s=>({s,m:s.dept===subj?0:1,cnt:Math.floor(rnd(s.id+'cvc')*6),clash:rnd(s.id+ids[0])<.2})).sort((a,b)=>a.m-b.m||a.cnt-b.cnt).slice(0,5);
  modal({title:'Choose a substitute',body:`<p class="ink2">Free teachers on the same campus, not on leave. Same subject first, then same grade. The count shows lessons covered this term.</p>${table(['Teacher','Subject match','Covered this term',''],cands.map(c=>`<tr><td>${esc(c.s.name)}</td><td>${c.m===0?pill('Same subject','good'):'-'}</td><td>${c.cnt}</td><td class="r">${c.clash?pill('Already has a lesson that period','warn'):''} <button class="btn btn-dark btn-sm" data-act="ncgo" data-ids="${ids.join(',')}" data-n="${esc(c.s.name)}">Assign</button></td></tr>`),{cls:'dense'})}`})}
act('ncassign',el=>ncPick([el.dataset.id]));act('ncbulk',()=>ncPick(Object.keys(S.ui.ncSel).filter(k=>S.ui.ncSel[k])));
act('ncgo',el=>{ST('needCover',[]).filter(l=>el.dataset.ids.split(',').includes(l.id)).forEach(l=>{l.cover=el.dataset.n;l.st='open'});S.ui.ncSel={};persist();closeLayer();toast('Assigned. The substitute and the absent teacher are notified.');render()});
