act('rolebulk',()=>toast('Choose a file in the guided import to assign roles in bulk.'));
route('audit',{roles:['admin'],title:'Audit log',sample:[[]],rows:['Platform Foundation / User Activity Audit Log','Platform Foundation / Staff Data Access Rules'],
  render(){const q=(S.ui.aq||'').toLowerCase();const L=[['09:12','Ms. Anjali Rao','Viewed','Student profile: Diya Sharma'],['09:05','Ms. Anjali Rao','Changed','English feedback: Aarav Mehta'],['08:50','Ms. Meera Mudbidri','Viewed','Teachers in my scope'],['08:31','Mrs. Lakshmi Nair','Exported','Workload table'],['08:10','Dr. Suresh Iyer','Viewed','Scorecard: Attendance rate'],['Yesterday 17:40','Ms. Deepa Kulkarni','Changed','Template: Grade 1 template proposal 2026-27 v1']].filter(r=>!q||r.join(' ').toLowerCase().includes(q));
    return `<div class="page">${pageHead('Audit log','Who viewed or changed student and staff data, and when. Staff data views are recorded here too.',`<button class="btn btn-ghost" data-act="auexp">${ic('down')}Export</button>`)}<div class="toolbar"><label class="search">${ic('search')}<input class="input" data-in="aq" placeholder="Search the log" value="${esc(S.ui.aq||'')}"></label></div>${card('',table(['When','Person','Action','What'],L.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`),{cls:'dense'}),{flush:true})}</div>`}});
INPUT.aq=el=>{S.ui.aq=el.value;const p=el.selectionStart;render();const n=document.querySelector('[data-in="aq"]');if(n){n.focus();n.setSelectionRange(p,p)}};act('auexp',()=>{download('audit-log.csv','When,Person,Action,What\n09:12,Anjali Rao,Viewed,Student profile');toast('Exported.','down')});
route('retention',{roles:['admin'],title:'Retention and requests',sample:[[]],rows:['Platform Foundation / Retention, Deletion and Data Request Tooling','Platform Foundation / Register Phase 2 Data Types in Retention Tooling'],
  render(){const R=[['Student and staff records','Placeholder: agreed with the school'],['Generated reports','Placeholder'],['AI interaction logs','Placeholder'],['Audit logs','Placeholder'],['Calendar meeting metadata','Placeholder'],['360 results','Placeholder'],['Observations','Placeholder'],['Development and lesson plans','Placeholder']];return `<div class="page">${pageHead('Retention and requests','The school is the data controller. Periods, consent and hosting region come from the school and its counsel. SchoolOS provides the tooling.')}${card('Retention per data type',table(['Data type','Period',''],R.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td class="r"><button class="btn btn-ghost btn-sm" data-act="retjob" data-n="${esc(r[0])}">Run delete or anonymise job</button></td></tr>`),{cls:'dense'}),{flush:true})}${card('Data request',`<div class="row"><input class="input" style="max-width:320px" placeholder="Search a person"><button class="btn btn-dark" data-act="retreq">Export their data</button></div>`)}</div>`}});
act('retjob',el=>toast(`Dry run for ${el.dataset.n}: 0 records are past their period.`));act('retreq',()=>toast('Export prepared for the person you searched.','down'));
route('ai-gov',{roles:['admin'],title:'AI governance',sample:[[],['log'],['controls'],['review']],rows:['AI Platform & Governance / Allowed-Inference Policy and Guardrails','AI Platform & Governance / AI Interaction Log','AI Platform & Governance / AI Usage Controls and Cost Limits','AI Platform & Governance / Human Review and Feedback','AI Platform & Governance / Model Gateway and Routing','AI Platform & Governance / Student Data Pseudonymisation and Re-Linking','AI Platform & Governance / Prompt and Policy Versioning'],
  render(a){const tab=a[0]||'policy',ctl=aiCtl();let b='';
    if(tab==='policy')b=card('What AI may and may not conclude',table(['Rule','How it is enforced'],[['No ranking or penalising of teachers','Questions refused. Outputs checked'],['No labels on children','Wording checked. Hedged language'],['No predictions about who will leave','Questions refused'],['No wellbeing, conduct, pay, age or health data','Never sent to a model'],['Student names replaced by codes before a model call','Re-linked only inside SchoolOS. This reduces exposure but is not anonymisation']].map(r=>`<tr><td class="wrap">${r[0]}</td><td class="wrap">${r[1]}</td></tr>`),{cls:'dense'}),{flush:true,aside:'<span class="muted sm">Prompt version v1.3 &middot; models routed by use case and cost</span>'});
    if(tab==='log'){const L=ST('aiLog',[]);b=card('Every AI request',L.length?table(['When','User','Role','Scope','Question','Result'],L.slice(0,20).map(l=>`<tr><td>${l.t}</td><td>${esc(l.user)}</td><td>${l.role}</td><td class="wrap">${esc(l.scope)}</td><td class="wrap">${esc(l.q)}</td><td class="wrap">${esc(l.res)}</td></tr>`),{cls:'dense'}):empty('No AI requests yet. Ask a question in Ask SchoolOS to see it logged here.'),{flush:true})}
    if(tab==='controls')b=card('Who can use AI, and limits',table(['Role','AI enabled'],ROLES_AI.map(k=>`<tr><td>${USERS[k].role}</td><td><label class="switch"><input type="checkbox" data-ch="aien" data-k="${k}" ${ctl.enabled[k]?'checked':''}><span>${ctl.enabled[k]?'On':'Off'}</span></label></td></tr>`),{cls:'dense'}),{flush:true})+card('Limits',`<div class="row"><div class="field"><label>Questions per user per day</label><input class="input sm num" style="width:120px" type="number" data-in="ailim" value="${ctl.limit}"></div><div class="field"><label>Monthly spend alert</label><input class="input sm num" style="width:120px" value="Placeholder"></div><label class="switch right"><input type="checkbox" data-ch="aikill" ${ctl.kill?'checked':''}><span>Kill switch: turn all AI off</span></label></div>`);
    if(tab==='review'){const F=ST('aiFlags',[]);b=card('Flagged answers',F.length?table(['When','User','Question','Answer','Status',''],F.map((f,i)=>`<tr><td>${f.t}</td><td>${esc(f.user)}</td><td class="wrap">${esc(f.q)}</td><td class="wrap">${esc(f.title)}</td><td>${f.state==='new'?pill('New','warn'):pill('Added to test set','good')}</td><td class="r"><button class="btn btn-ghost btn-sm" data-act="aifl" data-i="${i}">Add to test set</button></td></tr>`),{cls:'dense'}):empty('Nothing flagged. Users flag answers from Ask SchoolOS.'),{flush:true})}
    return `<div class="page">${pageHead('AI governance','The rules on what AI may conclude, a record of every request, who can use it, and a queue for answers people flag.')}${tabsBar('ai-gov',[['policy','Policy'],['log','Interaction log'],['controls','Usage controls'],['review','Review queue']],tab)}${b}</div>`}});
CHANGE.aien=el=>{aiCtl().enabled[el.dataset.k]=el.checked;persist();render()};CHANGE.aikill=el=>{aiCtl().kill=el.checked;persist();toast(el.checked?'All AI features are off.':'AI features are on.')};INPUT.ailim=el=>{aiCtl().limit=+el.value;persist()};act('aifl',el=>{ST('aiFlags',[])[+el.dataset.i].state='test';persist();render()});

/* ---------- achievement categories (iSAMS to report categories) ---------- */
route('ach-map',{roles:['admin'],title:'Achievement categories',sample:[[]],rows:[],
  render(){const M=ST('achMap',()=>[['Sports Day','Sports'],['Inter-house debate','Arts'],['Community service','Community'],['Science fair','Projects'],['Internship placement','Internships'],['Music exam','Arts'],['Miscellaneous award','']]);const un=M.filter(x=>!x[1]).length;
    return `<div class="page">${pageHead('Achievement categories','Achievements are recorded in iSAMS and pulled in nightly, so teachers never retype them. Map each iSAMS category to the group shown on the report. Anything unmapped is held back from reports until mapped.')}${un?`<div class="callout warn">${un} unmapped category is held back from reports.</div>`:''}${card('',table(['iSAMS category or type','Report category'],M.map((m,i)=>`<tr><td>${esc(m[0])}</td><td>${select('am'+i,[['','Not mapped'],...ACH_CATS],m[1],`data-ch="achmap" data-i="${i}"`)}</td></tr>`),{cls:'dense'}),{flush:true,aside:src('isams')})}</div>`}});
CHANGE.achmap=el=>{ST('achMap',[])[+el.dataset.i][1]=el.value;persist();render()};
/* ---------- duplicate comment flags: Grade Coordinator override ---------- */
route('dup-flags',{roles:['grade'],title:'Duplicate comments',sample:[[]],rows:[],
  render(){const D=ST('dupOv',{});const L=[['c1-1A-04','English (Ms. Anjali Rao)','Theme Based Learning (Dev Sharma)'],['c1-1B-07','English','Art']].filter(x=>STUDENTS[x[0]]);
    return `<div class="page">${pageHead('Duplicate comments','When two teachers wrote near-identical comments for the same student, the report shows it once. As Grade Coordinator you can override that for your grade.')}${card('',table(['Student','Comments that repeat','On the report',''],L.map(x=>`<tr><td>${esc(STUDENTS[x[0]].name)}</td><td class="wrap">${x[1]} and ${x[2]}</td><td>${D[x[0]]?pill('Both shown (overridden)','info'):pill('Shown once','good')}</td><td class="r"><button class="btn btn-ghost btn-sm" data-act="dupov" data-id="${x[0]}">${D[x[0]]?'Undo override':'Override: show both'}</button></td></tr>`),{cls:'dense'}),{flush:true})}</div>`}});
act('dupov',el=>{const D=ST('dupOv',{});D[el.dataset.id]=!D[el.dataset.id];persist();toast(D[el.dataset.id]?'Override saved.':'Override removed.');render()});
